#!/usr/bin/env bash
# Test runner for minic.  Usage: tests/run_tests.sh path/to/minic
#
# 1. programs/*.mc      output must equal programs/*.expected, with AND without
#                       the optimizer (the optimizer must never change meaning).
# 2. errors/*.mc        must exit with the code in *.exit and print the text in
#                       *.stderr (substring match). Optional *.args holds flags.
# 3. optimizer checks   assertions about the generated bytecode.
set -u

MINIC="${1:?usage: run_tests.sh path/to/minic}"
DIR="$(cd "$(dirname "$0")" && pwd)"
pass=0
fail=0

ok()  { pass=$((pass + 1)); printf '  PASS  %s\n' "$1"; }
bad() { fail=$((fail + 1)); printf '  FAIL  %s\n' "$1"; [ -n "${2:-}" ] && printf '        %s\n' "$2"; }

echo "== programs (optimized and unoptimized) =="
for src in "$DIR"/programs/*.mc; do
    name="$(basename "$src" .mc)"
    expected="$DIR/programs/$name.expected"
    for mode in "" "--no-opt"; do
        label="$name ${mode:-(opt)}"
        actual="$("$MINIC" "$src" $mode 2>&1)"
        if [ "$actual" == "$(cat "$expected")" ]; then ok "$label"
        else bad "$label" "got: $(printf '%s' "$actual" | head -c 200 | tr '\n' ' ')"; fi
    done
done

echo "== error handling =="
for src in "$DIR"/errors/*.mc; do
    name="$(basename "$src" .mc)"
    want_exit="$(cat "$DIR/errors/$name.exit")"
    want_msg="$(cat "$DIR/errors/$name.stderr")"
    args=""
    [ -f "$DIR/errors/$name.args" ] && args="$(cat "$DIR/errors/$name.args")"
    stderr="$("$MINIC" "$src" $args 2>&1 >/dev/null)"
    code=$?
    if [ "$code" == "$want_exit" ] && [[ "$stderr" == *"$want_msg"* ]]; then ok "$name"
    else bad "$name" "exit=$code (want $want_exit), stderr='$stderr'"; fi
done

echo "== optimizer =="
# Everything in constant_folding's first line should collapse to a single PUSH 10.
asm="$("$MINIC" "$DIR/programs/constant_folding.mc" --no-run --disasm)"
first_two="$(printf '%s\n' "$asm" | head -2 | awk '{print $2, $3}' | tr '\n' ' ')"
if [ "$first_two" == "PUSH 10 PRINT  " ] || [ "$first_two" == "PUSH 10 PRINT " ]; then ok "2*3+4 folds to PUSH 10"
else bad "2*3+4 folds to PUSH 10" "first instructions: $first_two"; fi

noopt_len="$("$MINIC" "$DIR/programs/constant_folding.mc" --no-run --disasm --no-opt | wc -l)"
opt_len="$("$MINIC" "$DIR/programs/constant_folding.mc" --no-run --disasm | wc -l)"
if [ "$opt_len" -lt "$noopt_len" ]; then ok "optimized bytecode is shorter ($opt_len < $noopt_len)"
else bad "optimized bytecode is shorter" "opt=$opt_len noopt=$noopt_len"; fi

stats="$("$MINIC" "$DIR/programs/dead_code.mc" --no-run --stats 2>&1)"
if [[ "$stats" == *"dead branches: 5"* && "$stats" == *"dead loops: 1"* ]]; then ok "dead_code stats (5 branches, 1 loop)"
else bad "dead_code stats" "$stats"; fi

echo
echo "passed: $pass   failed: $fail"
[ "$fail" -eq 0 ]
